// M1 🔮 จำลองชีวิตก่อนเลือก (ทุกโลก)
// =====================================================================
const SIMQ=[
 {t:'ทางแยกที่หนึ่ง: ข้อเสนอจากคนแปลกหน้า',x:'ชายใส่หน้ากากเสนอสิ่งที่คุณต้องการที่สุด แลกกับ “สัญญาหนึ่งข้อที่จะบอกทีหลัง”',o:[['รับข้อเสนอ',{pow:12,karma:-6},'คุณแข็งแกร่งขึ้นทันที — สามปีต่อมาเขากลับมาทวงสัญญา'],['ปฏิเสธ',{int:5},'ไม่มีอะไรเกิดขึ้น และนั่นคือความปลอดภัย'],['ตามเขาไปดูว่าเป็นใคร',{fame:800,hp:-20},'คุณเจอรังของเขา และรู้ความลับที่ไม่ควรรู้']]},
 {t:'ทางแยกที่สอง: คนที่คุณรักป่วยหนัก',x:'ยารักษามีอยู่ขวดเดียว อยู่ในมือคนที่คุณเกลียดที่สุด',o:[['ขอร้องเขา',{karma:8,fame:-300},'เขาให้ยา — และให้คุณคุกเข่าต่อหน้าทุกคน'],['ขโมยมา',{karma:-8,happy:6},'คนที่คุณรักหาย แต่ไม่รู้ว่าคุณทำอะไรไป'],['หายาเอง',{int:6,hp:-15},'คุณเจอสมุนไพรทันเวลาแบบหวุดหวิด']]},
 {t:'ทางแยกที่สาม: ประตูสองบาน',x:'บานหนึ่งพาไปสู่ชื่อเสียง อีกบานพาไปสู่ความสงบ',o:[['ประตูแห่งชื่อเสียง',{fame:2500,happy:-6},'ทุกคนรู้จักคุณ แต่ไม่มีใครรู้จักคุณจริงๆ'],['ประตูแห่งความสงบ',{happy:12,karma:5},'ไม่มีใครจำชื่อคุณได้ และคุณยิ้มทุกเช้า'],['ทุบประตูทั้งสอง',{pow:10,hp:-20},'ระบบขึ้นข้อความ [ผลลัพธ์นอกการจำลอง]']]}];
A.sim={w:CLS.concat(MW),ic:'🔮',n:'จำลองชีวิตก่อนเลือก',ok:()=>S.age>=14,gap:[2,4],st:[
 F=>{F.ch=3;F.lie=0;ask('🔮 ระบบจำลองชีวิต',`${tg('🔮 ระบบจำลอง')}<br>หน้าต่างสีม่วงลอยขึ้นตรงหน้า <b>[ระบบจำลองชีวิต · ทดลองใช้]</b><br>“ทุกครั้งที่เจอทางแยกใหญ่ ท่านจำลองดูอนาคตได้ก่อนเลือก <b>เหลือ 3 ครั้ง</b> ตลอดชีวิต”`,[['รับระบบ','',()=>fx({int:3},'🔮 ระบบติดตั้งเสร็จ โลโก้รูปดวงตากะพริบหนึ่งครั้ง')],['ปฏิเสธ','',()=>{F.ch=0;fx({},'🔮 ระบบตอบ “ไม่เป็นไร เราจะรอ”')}]])},
 F=>q(F,0),F=>q(F,1),F=>q(F,2),
 F=>{ask('🔃 ใครเป็นคนจำลอง',`หน้าต่างสีม่วงขึ้นมาครั้งสุดท้าย — แต่ครั้งนี้มีใบหน้าในนั้น <b>ใบหน้าของคุณเอง แก่กว่านี้ห้าสิบปี</b><br>“ข้าคือเจ้าในอนาคต ข้าจำลองทุกทางให้เจ้าดู${F.lie?` — และข้าโกหกเจ้า ${F.lie} ครั้ง`:''} เพราะทุกทางที่ “ดีที่สุด” ในการจำลอง จบที่ข้าคนนี้ ข้าอยากให้เจ้าไม่เหมือนข้า”`,[
  ['ขอบคุณตัวเองในอนาคต','',()=>fx({karma:12,int:8,happy:8},'🔮 หน้าต่างแตกเป็นผงม่วง ชีวิตที่เหลือไม่มีใครจำลองให้อีกแล้ว','myth')],
  ['ถามว่าทางไหนดีที่สุดจริงๆ','',()=>fx({int:12},'🔮 “ทางที่เจ้าไม่จำลองก่อนเลือก” — แล้วระบบก็ปิดตัวลงตลอดกาล','myth')]]);kAdd('รู้ว่าระบบจำลองชีวิตคือตัวเองในอนาคต')}]};
function q(F,i){const Q=SIMQ[i];const opts=Q.o.map(([t,o,r],j)=>[t,'',()=>fx(o,`🔮 ${Q.t.split(':')[0]} — ${r}`,o.fame>=2000||o.pow>=10?'epic':'')]);
 const lie=i>=1&&P(.4);ask(`🔮 ${Q.t}`,`${Q.x}<br><span class="tag2">จำลองได้อีก ${F.ch} ครั้ง</span>`,[...opts,F.ch>0?['🔮 จำลองดูก่อน','ใช้ 1 ครั้ง',()=>{F.ch--;if(lie)F.lie++;const sh=Q.o.map(([t,o,r],j)=>{const rr=lie&&j===0?Q.o[1][2]:lie&&j===1?Q.o[0][2]:r;return`<b>${t}</b>: ${rr}`}).join('<br>');ask(`🔮 ผลจำลอง`,`${sh}${i>=2&&F.lie?'<br><span class="tag2">⚠️ ภาพบางส่วนกระตุกแปลกๆ</span>':''}`,opts)}]:null])}

