const IMM=[['☁️','ท่านเซียนกระบี่หยก'],['🦊','ท่านหญิงจิ้งจอกเก้าหาง'],['🐢','ผู้เฒ่าเต่าพันปี'],['⚡','จ้าวสายฟ้า']];
A.line={w:MW,ic:'📱',n:'กลุ่มไลน์ผู้ฝึกตน',ok:()=>S.age>=15&&S.age<=45,gap:[1,3],st:[
 F=>{F.tr=0;chat('🏮 สมาคมผู้ฝึกตนแห่งเก้าสวรรค์',[[IMM[0][0]+' '+IMM[0][1],'ใครดึงมนุษย์เข้ากลุ่มเนี่ย'],[IMM[2][0]+' '+IMM[2][1],'ระบบสุ่มเชิญจ้า ข้ากดผิด'],[IMM[1][0]+' '+IMM[1][1],'น้องมนุษย์ อยู่เมืองไหนจ๊ะ ช่วยอะไรพี่อย่างได้มั้ย'],[IMM[1][0]+' '+IMM[1][1],'ชานมไข่มุกที่คนในโลกมนุษย์ชอบ มันคืออะไร พี่อยากลอง 🥺']],['“ได้ครับ เดี๋ยวสั่งไรเดอร์ไปให้ ส่งที่อยู่มาเลย”','“พวกคุณเป็นมิจฉาชีพแน่ๆ”','ออกจากกลุ่ม'],j=>{if(j===2){F.out=1;return fx({},'📱 สองนาทีต่อมา คุณถูกดึงกลับเข้ากลุ่ม “ห้ามออก ข้ายังไม่ได้ชานม”')}F.tr+=j===0?2:0;fx(j===0?{money:-1,happy:5}:{int:2},j===0?'🧋 คืนนั้นมีกล่องไม้แกะสลักวางหน้าห้อง ข้างในคือ<b>โอสถทิพย์หนึ่งเม็ด</b> กับโน้ต “อร่อยมาก ขอหวานน้อยด้วยรอบหน้า”':'📱 ทั้งกลุ่มส่งสติกเกอร์หัวเราะ')})},
 F=>{const pr=rp(['โหลดแอปธนาคารให้','สอนเปลี่ยนรูปโปรไฟล์','ไปจองคิวร้านหมูกระทะ','สอนใช้ฟิลเตอร์หน้าใส']);chat('🏮 สมาคมผู้ฝึกตนแห่งเก้าสวรรค์',[[IMM[3][0]+' '+IMM[3][1],`น้องมนุษย์ ข้าขอ${pr}`],[IMM[0][0]+' '+IMM[0][1],'แลกกับเคล็ดวิชาหนึ่งบท เอาไหม'],[IMM[2][0]+' '+IMM[2][1],'อย่าให้มากเกิน เดี๋ยวสวรรค์ชั้นสามรู้'],[IMM[1][0]+' '+IMM[1][1],'ชั้นสามมันอ่านแชตเราอยู่นะ 👀']],['ช่วยทันที แลกเคล็ดวิชา','ขอเป็นยาอายุวัฒนะแทน','ถามว่า “สวรรค์ชั้นสามคือใคร”'],j=>{if(j===0){F.tr+=2;fx({pow:12,int:4},'📜 เคล็ดวิชาถูกส่งมาเป็นไฟล์ PDF ชื่อ “ห้ามแชร์_final_v3.pdf”','epic')}else if(j===1){F.tr+=1;fx({life:5,hp:20},'💊 ยาเม็ดเล็กขนาดเม็ดพาราสีทอง')}else{F.sp=1;fx({int:6},'👁️ ข้อความถูกยกเลิกการส่งพร้อมกันทั้งกลุ่ม แล้วมีคนพิมพ์ “ทักแชตส่วนตัวมา”')}})},
 F=>{ask('⚠️ ผู้ดูแลกลุ่มคนใหม่',`ไลน์เด้งแจ้งเตือน: <b>“สวรรค์ชั้นสาม” ได้เข้าร่วมกลุ่ม</b> · <b>“สวรรค์ชั้นสาม” ลบ ${IMM[1][1]} ออกจากกลุ่ม</b><br>ข้อความเดียวที่ขึ้นมา: <i>“มนุษย์ที่ได้รับของจากสวรรค์โดยไม่ผ่านการฝึก ต้องถูกลบ”</i>`,[
  ['ทักแชตส่วนตัวไปหาท่านหญิงจิ้งจอก','',()=>{F.k='fox';fx({int:4},'🦊 “พี่ไม่เป็นไร แต่น้องต้องหนี — ชั้นสามไม่ได้ลบแค่จากกลุ่ม”')}],
  ['ลองสู้กับสิ่งที่ลงมา','มินิเกม: แตะ',()=>mg('tap','⚡ เทพจากชั้นสาม','แตะสายฟ้าที่ผ่าลงมา',{n:12,ic:'⚡'},sc=>{F.k=sc>=.6?'win':'lose';fx(sc>=.6?{pow:10,fame:1500}:{hp:-40},sc>=.6?'⚡ <b>มนุษย์คนแรกที่รับสายฟ้าสวรรค์ได้กลางคอนโด</b>':'🩸 ไฟดับทั้งตึก คุณรอดเพราะเซียนเต่าส่งกระดองมาบังไว้',sc>=.6?'myth':'bad')})]])},
 F=>chat('🏮 สมาคมผู้ฝึกตนแห่งเก้าสวรรค์',[[IMM[2][0]+' '+IMM[2][1],'เรื่องจริงคือ…'],[IMM[2][0]+' '+IMM[2][1],'ระบบไม่ได้ดึงน้องเข้ากลุ่มผิด'],[IMM[2][0]+' '+IMM[2][1],'น้องเคยเป็น<b>ผู้ก่อตั้งกลุ่มนี้</b> ก่อนจะเลือกลงมาเกิดเป็นมนุษย์'],[IMM[0][0]+' '+IMM[0][1],'และชั้นสามก็คือคนที่น้องเคยเตะออกจากกลุ่มเมื่อหมื่นปีก่อน 😅'],['ระบบ','คุณได้รับสิทธิ์ “แอดมินกลุ่ม” คืนแล้ว']],['เตะสวรรค์ชั้นสามออกจากกลุ่ม','เชิญสวรรค์ชั้นสามกลับมาคุยกันดีๆ','ยกแอดมินให้ท่านหญิงจิ้งจอก แล้วใช้ชีวิตมนุษย์ต่อ'],j=>{fx(j===0?{pow:15,fame:3000}:j===1?{karma:20,int:8}:{happy:15,karma:10},j===0?'📱 <b>“สวรรค์ชั้นสาม” ถูกนำออกจากกลุ่ม</b> ฟ้าทั้งเมืองสว่างวาบหนึ่งครั้ง':j===1?'🤝 ชั้นสามตอบกลับเป็นสติกเกอร์ร้องไห้ “ข้ารอคำนี้มาหมื่นปี”':'🦊 ท่านหญิงจิ้งจอกส่งชานมมาให้ทุกวันเกิด',j===2?'epic':'myth');kAdd('เปิดความลับกลุ่มไลน์ผู้ฝึกตน')})]};

