A.cdo={w:['ghost','zombie','normal'],ic:'🏚️',n:'คอนโดปีศาจแห่งความปรารถนา',ok:()=>S.age>=18&&S.age<=45,gap:[1,1],st:[
 F=>{F.ds=20;F.nb=MH.nm();F.gd=MH.nm();ask('🏚️ ห้อง 1407',`${tg('🏚️ สยองเอาชีวิตรอด')}<br>คอนโดย่านรังสิตปิดตาย ประตูทุกบานล็อกจากข้างนอก คนข้างห้องห้อง 1408 กลายเป็น<b>ปีศาจทองคำ</b> — ทั้งตัวเป็นเหรียญ ร้องหาเงินไม่หยุด<br>ทุกคนที่มีความปรารถนาแรงจะกลายร่าง${meter('ความปรารถนาของคุณ',F.ds,'#c77dff')}`,[
  ['ลงไปล็อบบี้หาทางออก','มินิเกม: หลบเลน',()=>mg('lane','🏚️ บันไดหนีไฟ','หลบปีศาจในบันได',{n:9,ic:'👹'},sc=>{F.ds+=sc>=.7?5:15;fx(sc>=.7?{int:3}:{hp:-25},sc>=.7?'🏚️ ล็อบบี้มีคนรอดสิบคน — และยามคอนโด<b>'+E(F.gd)+'</b>ที่ไม่กลัวอะไรเลย':'🩸 คุณถึงล็อบบี้ได้แต่โดนกรงเล็บเฉี่ยว','')})],
  ['ขังตัวในห้อง','',()=>{F.ds+=10;fx({hp:-5},'🚪 สามวันในห้อง คุณเริ่มได้ยินเสียงตัวเองพูดว่า “อยากออกไป”')}]])},
 F=>ask('🏚️ สิ่งที่คุณอยากได้',`คนรอดในล็อบบี้แบ่งกลุ่ม — คนที่อยากได้อาวุธ คนที่อยากหนี คนที่อยากรู้ว่าเกิดอะไรขึ้น<br>${meter('ความปรารถนาของคุณ',F.ds,'#c77dff')}`,[
  ['อยากปกป้องทุกคน','ความปรารถนาเพิ่มแรง',()=>{F.ds+=25;F.wh='protect';fx({karma:8})}],
  ['อยากรอดคนเดียว','',()=>{F.ds+=20;F.wh='alone';fx({karma:-5})}],
  ['ไม่อยากอะไรเลย','มินิเกม: ประคองสมดุล',()=>c2('balance','🧘 สงบใจ','ประคองจิตให้นิ่ง',sc=>{F.ds+=sc>=.6?-15:10;F.wh='none';fx({int:5},sc>=.6?'🧘 แถบความปรารถนาลดลงเป็นครั้งแรก':'🧘 ยิ่งพยายามไม่อยาก ยิ่งอยาก')})]]),
 F=>ask(F.ds>=60?'🦋 คุณเริ่มกลายร่าง':'🛡️ ยามคอนโด',F.ds>=60?`ผิวคุณเริ่มแตกเป็นเกล็ด แต่<b>คุณยังคิดได้</b> — ปีศาจของ “${F.wh==='protect'?'ความอยากปกป้อง':F.wh==='alone'?'ความอยากรอด':'ความว่างเปล่า'}” ไม่ได้ทำร้ายคน${meter('ความปรารถนาของคุณ',F.ds,'#c77dff')}`:`${E(F.gd)}ยามคอนโดเดินผ่านปีศาจทุกตัวโดยไม่มีตัวไหนแตะเขาเลย “ผมไม่อยากได้อะไรมาสิบปีแล้ว”${meter('ความปรารถนาของคุณ',F.ds,'#c77dff')}`,[
  ['ใช้ร่างปีศาจสู้','มินิเกม: แตะ',()=>mg('tap','🦋 ปีศาจแห่งความปรารถนา','ปกป้องคนในล็อบบี้',{n:12,ic:'👹'},sc=>fx(sc>=.6?{pow:12,karma:8}:{hp:-30},sc>=.6?'🦋 คนในล็อบบี้มองคุณด้วยความกลัวและขอบคุณพร้อมกัน':'🩸 ร่างนี้ยังคุมไม่อยู่',sc>=.6?'epic':'bad'))],
  ['ตามยามไปดูว่าเขาซ่อนอะไร','',()=>{F.k='gd';fx({int:6},`🔦 ห้องใต้ดินของ${E(F.gd)}มีจอนับสิบ — กล้องทุกตัวในคอนโด`)}]]),
 F=>{ask('🔃 คนที่ล็อกประตูจากข้างนอก',`ในห้องใต้ดิน ${E(F.gd)}ยอมรับ: “<b>ผมเป็นคนล็อกประตู</b> ปีศาจพวกนี้ออกไปข้างนอกไม่ได้ถ้าประตูล็อก — แต่คนรอดก็ออกไม่ได้เหมือนกัน ผมเลือกเมืองทั้งเมืองแทนคนในตึก”<br>แล้วเขาก็ยิ้ม “และคนเดียวที่เปิดประตูได้ คือคนที่ไม่อยากออกไป”${meter('ความปรารถนาของคุณ',F.ds,'#c77dff')}`,[
  [F.ds<40?'🚪 เปิดประตูด้วยใจว่างเปล่า':'🚪 พยายามเปิดประตู','',()=>{const w=F.ds<40||P(.3);fx(w?{fame:4000,karma:20,happy:10}:{hp:-35},w?'🚪 <b>ประตูเปิดออก</b> ปีศาจทุกตัวกลับเป็นคนในวินาทีที่แสงแดดส่องเข้ามา — ความปรารถนาที่ถูกขังหายไปพร้อมความมืด':'🚪 ประตูไม่ขยับ เพราะคุณอยากออกไปมากเกินไป',w?'myth':'bad')}],
  ['🛡️ อยู่เฝ้าประตูแทนยาม','',()=>fx({karma:15,int:8},`🛡️ ${E(F.gd)}เดินออกไปครั้งแรกในรอบสิบปี — คุณนั่งดูจอแทน และเริ่มเข้าใจว่าทำไมเขาไม่อยากได้อะไรเลย`,'epic')]]);kAdd('รอดจากคอนโดปีศาจแห่งความปรารถนา')}]};

